      <ul>
        {visibleTasks.map((task) => (
          <li key={task.id}>{task.text}</li>
        ))}
      </ul>
      <p data-restantes>{remaining} restantes</p>
      <button onClick={() => setFilter("todas")}>Todas</button>
      <button onClick={() => setFilter("ativas")}>Ativas</button>
      <button onClick={() => setFilter("feitas")}>Feitas</button>
    </div>
  );
}

