// useState e useEffect já estão disponíveis — não precisa importar.
// O preview não tem localStorage: esta gaveta de mentira faz o papel dele.
const gaveta: Record<string, string> = {};

function useLocalStorage(chave: string, inicial: number) {
  const [valor, setValor] = useState<number>(() => {
    const salvo = gaveta[chave];
    return salvo === undefined ? inicial : JSON.parse(salvo);
  });

  useEffect(() => {
    gaveta[chave] = JSON.stringify(valor);
  }, [chave, valor]);

  return [valor, setValor] as const;
}

function Contador({ onMais }: { onMais: () => void }) {
  return <button data-mais onClick={onMais}>+1 tarefa feita</button>;
}

function Painel({ total }: { total: number }) {
  return <p data-painel>{total}</p>;
}

export default function App() {
  const [total, setTotal] = useLocalStorage("feitas", 0);
  return (
    <div className="p-4">
      <Contador onMais={() => setTotal(total + 1)} />
      <Painel total={total} />
    </div>
  );
}

instruction.text:
## type, props tipadas e o perigo do any

```tsx
type Task = {
  id: number;
  text: string;
  done: boolean;
};

type TaskItemProps = {
  task: Task;
  onToggle: (id: number) => void;
};

const [tasks, setTasks] = useState<Task[]>([]);
```

- `type Task` é a etiqueta do dado: todo objeto de tarefa **tem** que ter esses três campos, com esses tipos
- `useState<Task[]>([])` diz ao React: essa lista **só** guarda `Task`
- `any` é tirar a etiqueta: o TypeScript para de checar aquele valor, e o erro só aparece rodando
- um exemplo clássico: um campo de busca sempre entrega **texto** (`string`), mesmo quando a pessoa digita um número — comparar esse texto direto com um `id: number` nunca bate

spec.starter:
// useState e useEffect já estão disponíveis — não precisa importar.

