  id: number;
  text: string;
  done: boolean;
};

export default function App() {
  const [tasks, setTasks] = useState<Task[]>([
    { id: 1, text: "Estudar React", done: false },
    { id: 2, text: "Beber água", done: false },
    { id: 3, text: "Revisar TypeScript", done: false },
  ]);
  const [search, setSearch] = useState("");

  function toggleById(id: any) {
    setTasks(tasks.map((task) => (task.id === id ? { ...task, done: !task.done } : task)));
  }

  return (
    <div className="p-4">
      <input id="busca" className="border px-2" value={search} onChange={(e) => setSearch(e.target.value)} />
      <button id="marcar" onClick={() => toggleById(search)}>Marcar por número</button>
      <ul>
        {tasks.map((task) => (
          <li key={task.id}>
            <span className={task.done ? "line-through" : ""}>{task.text}</span>
          </li>
        ))}
      </ul>
    </div>
  );
}

